<script lang="ts">
 import { page } from '$app/state'; import { onMount } from 'svelte'; import { db } from '$lib/db'; import { createId } from '$lib/id'; import type { Drawing, Pt, PaletteSet } from '$lib/types'; import CornerPicker from '$lib/components/CornerPicker.svelte'; import { flattenImage, imagePalette } from '$lib/image/flatten';
 let drawing=$state<Drawing>(),file=$state<File>(),preview=$state(''),corners=$state<[Pt,Pt,Pt,Pt]>([{x:.05,y:.05},{x:.95,y:.05},{x:.95,y:.95},{x:.05,y:.95}]),photoSize=$state({width:1,height:1}),note=$state(''),ignorePaper=$state(true),busy=$state(false),error=$state('');
 onMount(async()=>{const id=page.params.id;if(id)drawing=await db.drawings.get(id);if(!drawing)error='Drawing not found.';});
 function choose(f?:File){if(!f)return;if(!f.type.startsWith('image/')){error='Please choose an image file.';return;}file=f;preview=URL.createObjectURL(f);error='';}
 async function save(){if(!drawing||!file)return;busy=true;error='';try{const source=corners.map(p=>({x:p.x*photoSize.width,y:p.y*photoSize.height})) as [Pt,Pt,Pt,Pt];const flatBlob=await flattenImage(file,source);const palette=await imagePalette(flatBlob,ignorePaper);await db.stages.add({id:createId(),drawingId:drawing.id,createdAt:Date.now(),originalBlob:file,flatBlob,corners:source,palette,note:note.trim()||undefined});location.href=`/drawing/${drawing.id}`;}catch(e){error=e instanceof Error?e.message:'Could not save this stage.';}finally{busy=false;}}
</script>
<div class="app"><header class="topbar"><a class="brand" href="/"><span class="brand-mark">✳</span>Skepanion</a><nav class="nav"><a href="/palettes">My colors</a></nav></header><a class="muted" href={`/drawing/${page.params.id}`}>← Back to drawing</a><p class="eyebrow">{drawing?.title??'Add a stage'}</p><h1>Add a progress photo</h1><p class="muted">Use a photo with the paper fully in view. We’ll straighten it and keep the original too.</p>
<section class="section card">{#if !file}<label class="button" for="photo">📷 Choose or take a photo</label><input id="photo" class="sr-only" type="file" accept="image/*" capture="environment" onchange={(e)=>choose(e.currentTarget.files?.[0])}/>{:else}<div style="text-align:center"><CornerPicker image={preview} bind:corners onready={(size)=>photoSize=size}/></div><div class="field"><label for="note">A note (optional)</label><input id="note" bind:value={note} maxlength="150" placeholder="What changed in this session?"/></div><label class="row" style="font-size:14px"><input type="checkbox" bind:checked={ignorePaper}/> Ignore near-white paper color</label><div class="row" style="margin-top:15px"><button class="button" disabled={busy} onclick={()=>void save()}>{busy?'Flattening and saving…':'Save this stage'}</button><button class="button secondary" onclick={()=>{file=undefined;URL.revokeObjectURL(preview);}}>Choose another</button></div>{/if}{#if error}<p role="alert" style="color:#a33">{error}</p>{/if}</section></div>
